//! Build information reported by `loom version` and `loomd --version`.

use std::fmt;

use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

// Constants generated by `build.rs` at compile time.
include!(concat!(env!("OUT_DIR"), "/build_info.rs"));

/// Test hook replacing the version both binaries report, in debug builds only
/// ([`VersionInfo::with_test_version`]).
pub const TEST_BUILD_VERSION_ENV: &str = "LOOM_TEST_BUILD_VERSION";

/// Build information embedded in a loom binary at compile time.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct VersionInfo {
    /// Release version: `LOOM_BUILD_VERSION` at build time, otherwise the crate version.
    pub version: String,
    /// Full git commit hash of the build, or `unknown` outside a git checkout.
    pub commit: String,
    /// Committer date of `commit` in strict ISO 8601, or `unknown` outside a git checkout.
    pub commit_date: String,
    /// Target triple the binary was compiled for.
    pub target: String,
    /// Release channel the binary was built for.
    pub channel: Channel,
    /// Cargo profile the binary was built with.
    pub profile: Profile,
}

impl VersionInfo {
    /// Returns the build information of the running binary.
    #[must_use]
    pub fn current() -> Self {
        Self {
            version: BUILD_VERSION.to_owned(),
            commit: BUILD_COMMIT.to_owned(),
            commit_date: BUILD_COMMIT_DATE.to_owned(),
            target: BUILD_TARGET.to_owned(),
            channel: BUILD_CHANNEL,
            profile: BUILD_PROFILE,
        }
    }

    /// `self` reporting `version` instead, in a debug build only: the value of the test hook
    /// `LOOM_TEST_BUILD_VERSION`, read by the binaries. Empty or `None`, or a release build:
    /// `self` unchanged.
    #[must_use]
    pub fn with_test_version(self, version: Option<&str>) -> Self {
        match version.map(str::trim).filter(|version| !version.is_empty()) {
            Some(version) if cfg!(debug_assertions) => Self {
                version: version.to_owned(),
                ..self
            },
            _ => self,
        }
    }
}

/// Human-readable form: the version on the first line, then one `field: value` line per field.
impl fmt::Display for VersionInfo {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        writeln!(f, "{}", self.version)?;
        writeln!(f, "commit:      {}", self.commit)?;
        writeln!(f, "commit_date: {}", self.commit_date)?;
        writeln!(f, "target:      {}", self.target)?;
        writeln!(f, "channel:     {}", self.channel)?;
        write!(f, "profile:     {}", self.profile)
    }
}

/// Release channel, set with `LOOM_CHANNEL` at build time.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
pub enum Channel {
    /// Tagged release.
    Stable,
    /// Prerelease built from every merge to `main`.
    Dev,
    /// Any other build, such as `cargo build` on a workstation. Default when `LOOM_CHANNEL` is unset.
    Local,
}

impl Channel {
    /// Name used in the JSON and human output.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Stable => "stable",
            Self::Dev => "dev",
            Self::Local => "local",
        }
    }
}

impl fmt::Display for Channel {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

/// Cargo profile family, as reported by Cargo's `PROFILE` build variable.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
pub enum Profile {
    /// `dev` or `test` profile, or a custom profile that inherits from them.
    Debug,
    /// `release` or `bench` profile, or a custom profile that inherits from them.
    Release,
}

impl Profile {
    /// Name used in the JSON and human output.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Debug => "debug",
            Self::Release => "release",
        }
    }
}

impl fmt::Display for Profile {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

#[cfg(test)]
mod tests {
    use super::{Channel, Profile, VersionInfo};
    use serde_json::json;

    fn sample() -> VersionInfo {
        VersionInfo {
            version: "0.1.0-dev.42".to_owned(),
            commit: "0123456789abcdef0123456789abcdef01234567".to_owned(),
            commit_date: "2026-10-12T10:00:00+02:00".to_owned(),
            target: "aarch64-apple-darwin".to_owned(),
            channel: Channel::Dev,
            profile: Profile::Release,
        }
    }

    #[test]
    fn test_version_hook_only_in_debug_builds() {
        assert_eq!(sample().with_test_version(None), sample());
        assert_eq!(sample().with_test_version(Some(" ")), sample());
        let expected = if cfg!(debug_assertions) {
            "99.0.0"
        } else {
            "0.1.0-dev.42"
        };
        assert_eq!(sample().with_test_version(Some("99.0.0")).version, expected);
    }

    #[test]
    fn serializes_every_field_with_lowercase_enums() {
        let value = serde_json::to_value(sample()).unwrap();
        assert_eq!(
            value,
            json!({
                "version": "0.1.0-dev.42",
                "commit": "0123456789abcdef0123456789abcdef01234567",
                "commit_date": "2026-10-12T10:00:00+02:00",
                "target": "aarch64-apple-darwin",
                "channel": "dev",
                "profile": "release",
            })
        );
    }

    #[test]
    fn round_trips_through_json() {
        let text = serde_json::to_string(&sample()).unwrap();
        let back: VersionInfo = serde_json::from_str(&text).unwrap();
        assert_eq!(back, sample());
    }

    #[test]
    fn rejects_unknown_channel() {
        let mut value = serde_json::to_value(sample()).unwrap();
        value["channel"] = json!("nightly");
        assert!(serde_json::from_value::<VersionInfo>(value).is_err());
    }

    #[test]
    fn enum_names_match_serde() {
        for channel in [Channel::Stable, Channel::Dev, Channel::Local] {
            assert_eq!(
                serde_json::to_value(channel).unwrap(),
                json!(channel.as_str())
            );
        }
        for profile in [Profile::Debug, Profile::Release] {
            assert_eq!(
                serde_json::to_value(profile).unwrap(),
                json!(profile.as_str())
            );
        }
    }

    #[test]
    fn displays_one_field_per_line() {
        assert_eq!(
            sample().to_string(),
            "0.1.0-dev.42\n\
             commit:      0123456789abcdef0123456789abcdef01234567\n\
             commit_date: 2026-10-12T10:00:00+02:00\n\
             target:      aarch64-apple-darwin\n\
             channel:     dev\n\
             profile:     release"
        );
    }

    #[test]
    fn current_has_no_empty_field() {
        let info = VersionInfo::current();
        assert_ne!(info.version, "", "version is empty");
        assert_ne!(info.commit, "", "commit is empty");
        assert_ne!(info.commit_date, "", "commit_date is empty");
        assert_ne!(info.target, "", "target is empty");
    }
}
